//! Ergonomic, value-oriented representations of BMP390 registers.
//!
//! The types in this module convert to and from the bit-level register field
//! sets generated by [`device_driver`](https://docs.rs/device-driver). They do
//! not perform device I/O; use [`crate::Bmp390::device`] for that. Converting an
//! ergonomic value to a generated field set initializes all bits not represented
//! by the ergonomic type to zero.

use crate::raw::{self, field_sets};
use thiserror::Error;

/// An error caused by a reserved register value that has no ergonomic variant.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Error)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[error("reserved value {value} in register field {field}")]
pub struct ReservedValueError {
    /// The field containing the reserved value.
    pub field: &'static str,

    /// The reserved value.
    pub value: u8,
}

impl ReservedValueError {
    const fn new(field: &'static str, value: u8) -> Self {
        Self { field, value }
    }
}

/// Sensor error conditions from [`field_sets::ErrReg`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub struct ErrorStatus {
    /// Whether the sensor has encountered a fatal error.
    pub fatal: bool,

    /// Whether command execution failed. Cleared on read.
    pub command: bool,

    /// Whether the sensor configuration is invalid. Cleared on read.
    pub configuration: bool,
}

impl From<field_sets::ErrReg> for ErrorStatus {
    fn from(value: field_sets::ErrReg) -> Self {
        Self {
            fatal: value.fatal_err(),
            command: value.cmd_err(),
            configuration: value.conf_err(),
        }
    }
}

impl From<ErrorStatus> for field_sets::ErrReg {
    fn from(value: ErrorStatus) -> Self {
        let mut register = Self::new_zero();
        register.set_fatal_err(value.fatal);
        register.set_cmd_err(value.command);
        register.set_conf_err(value.configuration);
        register
    }
}

/// Sensor status flags from [`field_sets::Status`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub struct Status {
    /// Whether the command decoder can accept a command.
    pub command_ready: bool,

    /// Whether new pressure data is available.
    pub pressure_ready: bool,

    /// Whether new temperature data is available.
    pub temperature_ready: bool,
}

impl From<field_sets::Status> for Status {
    fn from(value: field_sets::Status) -> Self {
        Self {
            command_ready: value.command_ready() == raw::CommandStatus::Ready,
            pressure_ready: value.data_ready_pressure(),
            temperature_ready: value.data_ready_temperature(),
        }
    }
}

impl From<Status> for field_sets::Status {
    fn from(value: Status) -> Self {
        let mut register = Self::new_zero();
        register.set_command_ready(if value.command_ready {
            raw::CommandStatus::Ready
        } else {
            raw::CommandStatus::InProgress
        });

        register.set_data_ready_pressure(value.pressure_ready);
        register.set_data_ready_temperature(value.temperature_ready);
        register
    }
}

