/// Command accepted by the BMP390 command register.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub enum Command {
    /// No operation.
    Nop,

    /// Clear all FIFO data.
    FlushFifo,

    /// Reset the device and its user configuration.
    SoftReset,
}

impl TryFrom<raw::Command> for Command {
    type Error = ReservedValueError;

    fn try_from(value: raw::Command) -> Result<Self, Self::Error> {
        match value {
            raw::Command::Nop => Ok(Self::Nop),
            raw::Command::FifoFlush => Ok(Self::FlushFifo),
            raw::Command::SoftReset => Ok(Self::SoftReset),
            raw::Command::Reserved(value) => Err(ReservedValueError::new("cmd.cmd", value)),
        }
    }
}

impl From<Command> for raw::Command {
    fn from(value: Command) -> Self {
        match value {
            Command::Nop => Self::Nop,
            Command::FlushFifo => Self::FifoFlush,
            Command::SoftReset => Self::SoftReset,
        }
    }
}

/// Command register value represented by [`field_sets::CmdFieldsIn`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub struct CommandRegister {
    /// Command to execute.
    pub command: Command,
}

impl TryFrom<field_sets::CmdFieldsIn> for CommandRegister {
    type Error = ReservedValueError;

    fn try_from(value: field_sets::CmdFieldsIn) -> Result<Self, Self::Error> {
        Ok(Self {
            command: value.cmd().try_into()?,
        })
    }
}

impl From<CommandRegister> for field_sets::CmdFieldsIn {
    fn from(value: CommandRegister) -> Self {
        let mut register = Self::new_zero();
        register.set_cmd(value.command.into());
        register
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn infallible_registers_round_trip() {
        let errors = ErrorStatus {
            fatal: true,
            command: false,
            configuration: true,
        };
        assert_eq!(ErrorStatus::from(field_sets::ErrReg::from(errors)), errors);

        let status = Status {
            command_ready: true,
            pressure_ready: false,
            temperature_ready: true,
        };
        assert_eq!(Status::from(field_sets::Status::from(status)), status);

        let event = Event {
            power_on_reset: false,
            interface_activity: true,
        };
        assert_eq!(Event::from(field_sets::Event::from(event)), event);

        let interrupt_status = InterruptStatus {
            fifo_watermark: true,
            fifo_full: false,
            data_ready: true,
        };
        assert_eq!(
            InterruptStatus::from(field_sets::IntStatus::from(interrupt_status)),
            interrupt_status
        );

        let interrupt_control = InterruptControl {
            output: InterruptOutput::OpenDrain,
            level: InterruptLevel::ActiveLow,
            latched: true,
            fifo_watermark_enabled: false,
            fifo_full_enabled: true,
            drive_strength: false,
            data_ready_enabled: true,
        };
        assert_eq!(
            InterruptControl::from(field_sets::IntCtrl::from(interrupt_control)),
            interrupt_control
        );

        let power = PowerControl {
            pressure_enabled: true,
            temperature_enabled: false,
            mode: PowerMode::Forced,
        };
        assert_eq!(PowerControl::from(field_sets::PwrCtrl::from(power)), power);

        let filter = IirFilterConfig {
            coefficient: FilterCoefficient::Coefficient31,
        };
        assert_eq!(
            IirFilterConfig::from(field_sets::Config::from(filter)),
            filter
        );
    }

    #[test]
    fn fallible_registers_round_trip() {
        let oversampling = OversamplingConfig {
            pressure: Oversampling::X2,
            temperature: Oversampling::X16,
        };
        assert_eq!(
            OversamplingConfig::try_from(field_sets::Osr::from(oversampling)),
            Ok(oversampling)
        );

        let output_data_rate = OutputDataRateConfig {
            rate: OutputDataRate::Hz0P05,
        };
        assert_eq!(
            OutputDataRateConfig::try_from(field_sets::Odr::from(output_data_rate)),
            Ok(output_data_rate)
        );

        let command = CommandRegister {
            command: Command::FlushFifo,
        };
        assert_eq!(
            CommandRegister::try_from(field_sets::CmdFieldsIn::from(command)),
            Ok(command)
        );
    }

    #[test]
    fn every_enum_variant_round_trips() {
        for value in [InterruptOutput::PushPull, InterruptOutput::OpenDrain] {
            assert_eq!(InterruptOutput::from(raw::IntOpenDrain::from(value)), value);
        }

        for value in [InterruptLevel::ActiveLow, InterruptLevel::ActiveHigh] {
            assert_eq!(InterruptLevel::from(raw::IntLevel::from(value)), value);
        }

        for value in [PowerMode::Sleep, PowerMode::Forced, PowerMode::Normal] {
            assert_eq!(PowerMode::from(raw::MeasurementMode::from(value)), value);
        }

        for value in [
            Oversampling::X1,
            Oversampling::X2,
            Oversampling::X4,
            Oversampling::X8,
            Oversampling::X16,
            Oversampling::X32,
        ] {
            assert_eq!(
                Oversampling::try_from(raw::Oversampling::from(value)),
                Ok(value)
            );
        }

        for value in [
            OutputDataRate::Hz200,
            OutputDataRate::Hz100,
            OutputDataRate::Hz50,
            OutputDataRate::Hz25,
            OutputDataRate::Hz12P5,
            OutputDataRate::Hz6P25,
            OutputDataRate::Hz3P1,
            OutputDataRate::Hz1P5,
            OutputDataRate::Hz0P78,
            OutputDataRate::Hz0P39,
            OutputDataRate::Hz0P2,
            OutputDataRate::Hz0P1,
            OutputDataRate::Hz0P05,
            OutputDataRate::Hz0P02,
            OutputDataRate::Hz0P01,
            OutputDataRate::Hz0P006,
            OutputDataRate::Hz0P003,
            OutputDataRate::Hz0P0015,
        ] {
            assert_eq!(
                OutputDataRate::try_from(raw::OdrSel::from(value)),
                Ok(value)
            );
        }

        for value in [
            FilterCoefficient::Coefficient0,
            FilterCoefficient::Coefficient1,
            FilterCoefficient::Coefficient3,
            FilterCoefficient::Coefficient7,
            FilterCoefficient::Coefficient15,
            FilterCoefficient::Coefficient31,
            FilterCoefficient::Coefficient63,
            FilterCoefficient::Coefficient127,
        ] {
            assert_eq!(
                FilterCoefficient::from(raw::IirFilterCoefficient::from(value)),
                value
            );
        }

        for value in [Command::Nop, Command::FlushFifo, Command::SoftReset] {
            assert_eq!(Command::try_from(raw::Command::from(value)), Ok(value));
        }
    }

    #[test]
    fn reserved_values_report_their_field() {
        let mut oversampling = field_sets::Osr::new_zero();
        oversampling.set_pressure(raw::Oversampling::Reserved(6));
        assert_eq!(
            OversamplingConfig::try_from(oversampling),
            Err(ReservedValueError::new("osr.pressure", 6))
        );

        let mut oversampling = field_sets::Osr::new_zero();
        oversampling.set_temperature(raw::Oversampling::Reserved(7));
        assert_eq!(
            OversamplingConfig::try_from(oversampling),
            Err(ReservedValueError::new("osr.temperature", 7))
        );

        let mut output_data_rate = field_sets::Odr::new_zero();
        output_data_rate.set_odr_sel(raw::OdrSel::Reserved(31));
        assert_eq!(
            OutputDataRateConfig::try_from(output_data_rate),
            Err(ReservedValueError::new("odr.odr_sel", 31))
        );

        let mut command = field_sets::CmdFieldsIn::new_zero();
        command.set_cmd(raw::Command::Reserved(1));
        assert_eq!(
            CommandRegister::try_from(command),
            Err(ReservedValueError::new("cmd.cmd", 1))
        );
    }
}
